### Python

```python
import sys

# 外部函数：在 [1..n] 中选若干数使和为 k，返回升序列表；无解返回空列表
def pick_cards(n: int, k: int):
    S = n * (n + 1) // 2
    if k > S:
        return []  # 无解
    ans = []
    # 从大到小贪心选取
    for i in range(n, 0, -1):
        if k >= i:
            ans.append(i)
            k -= i
            if k == 0:
                break
    if k != 0:  # 理论上不会发生（k<=S 时必可表示）
        return []
    ans.reverse()  # 升序输出
    return ans

def main():
    data = list(map(int, sys.stdin.read().split()))
    it = iter(data)
    T = next(it)
    out_lines = []
    for _ in range(T):
        n = next(it); m = next(it)
        for _ in range(m):
            k = next(it)
            res = pick_cards(n, k)
            if not res:
                out_lines.append("-1")
            else:
                out_lines.append(str(len(res)))
                out_lines.append(" ".join(map(str, res)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
```

### Java

```java
import java.io.*;
import java.util.*;

/* ACM 风格主类 */
public class Main {

    // 外部函数：返回一个升序的选牌列表；无解返回空列表
    static List<Integer> pickCards(int n, long k) {
        long S = 1L * n * (n + 1) / 2;
        if (k > S) return Collections.emptyList(); // 无解
        ArrayList<Integer> ans = new ArrayList<>();
        // 从大到小贪心取数
        for (int i = n; i >= 1; i--) {
            if (k >= i) {
                ans.add(i);
                k -= i;
                if (k == 0) break;
            }
        }
        if (k != 0) return Collections.emptyList(); // 理论上不会发生
        Collections.reverse(ans); // 升序输出
        return ans;
    }

    public static void main(String[] args) throws Exception {
        // 使用 BufferedReader + StringTokenizer，简单高效
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        ArrayList<String> out = new ArrayList<>();
        st = new StringTokenizer(br.readLine());
        int T = Integer.parseInt(st.nextToken());
        for (int tc = 0; tc < T; tc++) {
            // 读取 n m
            st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());
            for (int q = 0; q < m; q++) {
                // 每个查询一行一个 k
                long k = Long.parseLong(br.readLine().trim());
                List<Integer> res = pickCards(n, k);
                if (res.isEmpty()) {
                    out.add("-1");
                } else {
                    out.add(String.valueOf(res.size()));
                    // 输出升序编号
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i < res.size(); i++) {
                        if (i > 0) sb.append(' ');
                        sb.append(res.get(i));
                    }
                    out.add(sb.toString());
                }
            }
        }
        // 统一输出
        StringBuilder all = new StringBuilder();
        for (int i = 0; i < out.size(); i++) {
            all.append(out.get(i)).append('\n');
        }
        System.out.print(all.toString());
    }
}
